<?php
declare(strict_types=1);namespace App\Command;
use App\Imperium\Runtime\Clavium\LegateProviderInvocationActivationService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\{InputArgument,InputInterface,InputOption};use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:clavium:activate-legate-provider-invocation',description:'Activate one exact provider invocation under an opaque bounded credential lease.')]
final class ClaviumActivateLegateProviderInvocationCommand extends Command{public function __construct(private readonly LegateProviderInvocationActivationService$service){parent::__construct();}protected function configure():void{$this->addArgument('turn-authorization-decision-id',InputArgument::REQUIRED)->addArgument('provider-activation-authority-id',InputArgument::REQUIRED)->addArgument('locksmith-binding-id',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->service->activate((string)$i->getArgument('turn-authorization-decision-id'),(string)$i->getArgument('provider-activation-authority-id'),(string)$i->getArgument('locksmith-binding-id'),new \DateTimeImmutable());}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}$o->writeln($i->getOption('json')?json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR):'<info>PROVIDER_INVOCATION_ACTIVATED_PENDING_ONE_TURN</info> '.$r['activation_id']);return self::SUCCESS;}}
